def parse_grid_section(s, label):
 m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n',s); h,w=map(int,m.groups()); start=m.end(); rows=[]
 for line in s[start:].splitlines():
  if re.fullmatch(r'(?:[0-9]+\s+)*[0-9]+',line.strip()):
   vals=list(map(int,line.split()))
   if len(vals)==w: rows.append(vals)
   else: break
   if len(rows)==h: break
  elif rows: break
 return rows
